Q_(a){return A.ck(a,null,this.a,null,"\u0905\u0938\u093e\u0907\u0928\u092e\u0947\u0902\u091f \u0915\u0947 \u0932\u093f\u090f 1 \u0921\u093f\u0932\u0940\u0935\u0930\u0940 \u092c\u093e\u0915\u0940","\u0905\u0938\u093e\u0907\u0928\u092e\u0947\u0902\u091f \u0915\u0947 \u0932\u093f\u090f "+a+" \u0921\u093f\u0932\u0940\u0935\u0930\u0940 \u092c\u093e\u0915\u0940",null,"\u0905\u0938\u093e\u0907\u0928\u092e\u0947\u0902\u091f \u0915\u0947 \u0932\u093f\u090f \u0915\u094b\u0908 \u0921\u093f\u0932\u0940\u0935\u0930\u0940 \u092c\u093e\u0915\u0940 \u0928\u0939\u0940\u0902")},
gQ0(){return"\u0939\u0930 \u0921\u093f\u0932\u0940\u0935\u0930\u0940 \u0915\u093f\u0938\u0940 \u0921\u094d\u0930\u093e\u0907\u0935\u0930 \u092f\u093e \u0938\u0947\u0932\u094d\u0938\u092e\u0948\u0928 \u0915\u094b \u0938\u094c\u0902\u092a\u0947\u0902 \u0924\u093e\u0915\u093f \u0909\u0928\u094d\u0939\u0947\u0902 \u092a\u0924\u093e \u091a\u0932\u0947 \u0915\u093f \u0906\u091c \u0915\u094d\u092f\u093e \u0921\u093f\u0932\u0940\u0935\u0930 \u0915\u0930\u0928\u093e \u0939\u0948\u0964"},
