ga19(){return"\u0906\u092a\u0942\u0930\u094d\u0924\u093f\u0915\u0930\u094d\u0924\u093e"},
ga14(){return"\u0921\u0941\u092a\u094d\u0932\u093f\u0915\u0947\u091f \u0915\u0947 \u092a\u093e\u0938 \u091c\u094b \u0915\u0941\u091b \u092d\u0940 \u0939\u0948 \u2014 \u091a\u093e\u0932\u093e\u0928, \u0932\u0947\u091c\u0930 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f\u092f\u093e\u0902, \u0921\u093f\u0932\u0940\u0935\u0930\u0940, \u0916\u0930\u0940\u0926, \u091c\u094b \u092d\u0940 \u0932\u093e\u0917\u0942 \u0939\u094b \u2014 \u0935\u0939 \u0909\u0938 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u092e\u0947\u0902 \u091a\u0932\u093e \u091c\u093e\u0924\u093e \u0939\u0948 \u091c\u093f\u0938\u0947 \u0906\u092a \u0930\u0916\u0924\u0947 \u0939\u0948\u0902\u0964 \u092b\u093f\u0930 \u0921\u0941\u092a\u094d\u0932\u093f\u0915\u0947\u091f \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0915\u094b \u0939\u091f\u093e \u0926\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964 \u0907\u0938\u0947 \u092a\u0942\u0930\u094d\u0935\u0935\u0924 \u0928\u0939\u0940\u0902 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0924\u093e\u0964"},
